function hollowCyl(cx,cy,cz,R,H,thick,type){
  for(let y=0;y<H;y++) for(let dx=-R;dx<=R;dx++) for(let dz=-R;dz<=R;dz++){
    let d=dx*dx+dz*dz;
    if(d<=R*R && d>=(R-thick)*(R-thick)) block(cx+dx,cy+y,cz+dz,type);
  }
}

