function tree(tx,ty,tz){
  box(tx-1,0,tz-1,tx+1,6,tz+1,'oak_log');
  for(let dy=7;dy<=14;dy++){
    let r=5-Math.floor(Math.abs(dy-10)*0.5);
    if(r<2) r=2;
    for(let dx=-r;dx<=r;dx++) for(let dz=-r;dz<=r;dz++)
      if(Math.abs(dx)+Math.abs(dz)<=r+1) block(tx+dx,ty+dy,tz+dz,'oak_leaves');
  }
}
